2	// and is safe to use from tests (point it at an httptest.Server via
3	// WithHTTPClient or a localhost baseURL).
4	package client
5	
6	import (
7		"context"
8		"encoding/json"
9		"errors"
10		"fmt"
11		"io"
12		"net/http"
13	
14		"github.com/immuta/operations/services/crow/pkg/api"
15	)
16	
17	type Client struct {
18		httpClient *http.Client
19		baseURL    string
20	}
21	
22	type Option func(*Client)
23	
24	// WithHTTPClient overrides the default *http.Client (useful for tests and
25	// for callers that want custom timeouts or transport).
26	func WithHTTPClient(h *http.Client) Option {
27		return func(c *Client) { c.httpClient = h }
28	}
29	
30	// New constructs a Client pointed at baseURL (e.g. "https://crow.infrastructure.immuta.io").
31	// baseURL must not end in "/".
32	func New(baseURL string, opts ...Option) *Client {
33		c := &Client{baseURL: baseURL, httpClient: http.DefaultClient}
34		for _, opt := range opts {
35			opt(c)
36		}
37		return c
38	}
39	
40	// Typed errors consumers can match with errors.Is.
41	var (
42		ErrAlreadyExists = errors.New("module version already exists")
43		ErrNotFound      = errors.New("module version not found")
44	)
45	
46	// Upload PUTs the given gzipped-tar body for the module version. It returns
47	// ErrAlreadyExists on HTTP 409, nil on 201, and a generic error otherwise.
48	func (c *Client) Upload(ctx context.Context, m api.Module, body io.Reader) error {
49		if err := m.Validate(); err != nil {
50			return err
51		}
52		if err := api.ValidateVersion(m.Version); err != nil {
53			return err
54		}
55		req, err := http.NewRequestWithContext(ctx, http.MethodPut, c.baseURL+m.UploadPath(), body)
56		if err != nil {
57			return err
58		}
59		req.Header.Set("Content-Type", "application/octet-stream")
60		resp, err := c.httpClient.Do(req)
61		if err != nil {
62			return err
63		}
64		defer resp.Body.Close()
65		switch resp.StatusCode {
66		case http.StatusCreated:
67			return nil
68		case http.StatusConflict:
69			return ErrAlreadyExists
70		default:
71			return fmt.Errorf("unexpected status %d uploading %s", resp.StatusCode, m.UploadPath())
72		}
73	}
74	
75	// Exists returns (true, nil) on 200 or 204, (false, nil) on 404, and an
76	// error for any other status.
77	func (c *Client) Exists(ctx context.Context, m api.Module) (bool, error) {
78		if err := m.Validate(); err != nil {
79			return false, err
80		}
81		req, err := http.NewRequestWithContext(ctx, http.MethodHead, c.baseURL+m.DownloadPath(), nil)
82		if err != nil {
83			return false, err
84		}
85		resp, err := c.httpClient.Do(req)
86		if err != nil {
87			return false, err
88		}
89		defer resp.Body.Close()
90		switch resp.StatusCode {
91		case http.StatusOK, http.StatusNoContent:
92			return true, nil
93		case http.StatusNotFound:
94			return false, nil
95		default:
96			return false, fmt.Errorf("unexpected status %d checking %s", resp.StatusCode, m.DownloadPath())
97		}
98	}
99	
100	// ListVersions returns the module's version list in server order.
101	// Returns ErrNotFound when the module has no published versions.
102	func (c *Client) ListVersions(ctx context.Context, id api.ModuleIdentifier) ([]string, error) {
103		if err := id.Validate(); err != nil {
104			return nil, err
105		}
106		req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+id.VersionsPath(), nil)
107		if err != nil {
108			return nil, err
109		}
110		resp, err := c.httpClient.Do(req)
111		if err != nil {
112			return nil, err
113		}
114		defer resp.Body.Close()
115		switch resp.StatusCode {
116		case http.StatusOK:
117			var body api.ListVersionsResponse
118			if err := json.NewDecoder(resp.Body).Decode(&body); err != nil {
119				return nil, fmt.Errorf("decoding response: %w", err)
120			}
121			if len(body.Modules) == 0 {
122				return nil, ErrNotFound
123			}
124			out := make([]string, len(body.Modules[0].Versions))
125			for i, v := range body.Modules[0].Versions {
126				out[i] = v.Version
127			}
128			return out, nil
129		case http.StatusNotFound:
130			return nil, ErrNotFound
131		default:
132			return nil, fmt.Errorf("unexpected status %d listing %s", resp.StatusCode, id.VersionsPath())
133		}
134	}
135	
136	// Download fetches the gzipped tarball bytes for the given module
137	// version. It follows the X-Terraform-Get redirect returned by Crow's
138	// 204 response (per the Terraform module registry protocol). The caller
139	// is responsible for closing the returned ReadCloser.
140	//
141	// Returns ErrNotFound on HTTP 404 from Crow.
142	func (c *Client) Download(ctx context.Context, m api.Module) (io.ReadCloser, error) {
143		if err := m.Validate(); err != nil {
144			return nil, err
145		}
146		req, err := http.NewRequestWithContext(ctx, http.MethodGet, c.baseURL+m.DownloadPath(), nil)
147		if err != nil {
148			return nil, err
149		}
150		resp, err := c.httpClient.Do(req)
151		if err != nil {
152			return nil, err
153		}
154	
155		// The protocol uses 204 + X-Terraform-Get to point clients at the
156		// real artifact location (S3 presigned URL in production).
157		if resp.StatusCode == http.StatusNotFound {
158			_ = resp.Body.Close()
159			return nil, ErrNotFound
160		}
161		if resp.StatusCode != http.StatusNoContent && resp.StatusCode != http.StatusOK {
162			_ = resp.Body.Close()
163			return nil, fmt.Errorf("unexpected status %d resolving %s", resp.StatusCode, m.DownloadPath())
164		}
165		location := resp.Header.Get("X-Terraform-Get")
166		_ = resp.Body.Close()
167		if location == "" {
168			return nil, fmt.Errorf("crow returned %d with no X-Terraform-Get header for %s", resp.StatusCode, m.DownloadPath())
169		}
170	
171		blobReq, err := http.NewRequestWithContext(ctx, http.MethodGet, location, nil)
172		if err != nil {
173			return nil, err
174		}
175		blobResp, err := c.httpClient.Do(blobReq)
176		if err != nil {
177			return nil, fmt.Errorf("fetching presigned blob: %w", err)
178		}
179		if blobResp.StatusCode != http.StatusOK {
180			_ = blobResp.Body.Close()
181			return nil, fmt.Errorf("unexpected status %d fetching blob %s", blobResp.StatusCode, location)
182		}
183		return blobResp.Body, nil
184	}
