package cmd

import (
	"archive/tar"
	"bytes"
	"compress/gzip"
	"context"
	"net/http"
	"net/http/httptest"
	"strings"
	"testing"
)

// fakeCrow with two versions of moduleA. v1 has main.tf; v2 has main.tf
// (modified) and a new variables.tf.
func fakeCrowTwoVersions(t *testing.T) *httptest.Server {
	t.Helper()
	mkTgz := func(files map[string]string) []byte {
		var buf bytes.Buffer
		gz := gzip.NewWriter(&buf)
		tw := tar.NewWriter(gz)
		for n, b := range files {
			_ = tw.WriteHeader(&tar.Header{Name: n, Mode: 0o644, Size: int64(len(b)), Typeflag: tar.TypeReg})
			_, _ = tw.Write([]byte(b))
		}
		_ = tw.Close()
		_ = gz.Close()
		return buf.Bytes()
	}
	v1 := mkTgz(map[string]string{"main.tf": "resource \"aws_s3_bucket\" \"alpha\" {}\n"})
	v2 := mkTgz(map[string]string{
		"main.tf":      "resource \"aws_s3_bucket\" \"beta\" {}\n",
		"variables.tf": "variable \"name\" { type = string }\n",
	})

	mux := http.NewServeMux()
	blob := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.URL.Path {
		case "/blob/1.0.0":
			_, _ = w.Write(v1)
		case "/blob/1.1.0":
			_, _ = w.Write(v2)
		default:
			http.NotFound(w, r)
		}
	}))
	t.Cleanup(blob.Close)
	mux.HandleFunc("/v1/modules/iac/comply/aws/", func(w http.ResponseWriter, r *http.Request) {
		parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/v1/modules/iac/comply/aws/"), "/")
		if len(parts) != 2 || parts[1] != "download" {
			http.NotFound(w, r)
			return
		}
		w.Header().Set("X-Terraform-Get", blob.URL+"/blob/"+parts[0])
		w.WriteHeader(http.StatusNoContent)
	})
	srv := httptest.NewServer(mux)
	t.Cleanup(srv.Close)
	return srv
}

func TestDiffPlainOutput(t *testing.T) {
	srv := fakeCrowTwoVersions(t)
	root := NewRootCmd()
	var stdout, stderr bytes.Buffer
	root.SetOut(&stdout)
	root.SetErr(&stderr)
	root.SetArgs([]string{
		"diff",
		"iac/comply/aws", "1.0.0", "1.1.0",
		"--crow-url", srv.URL,
		"--plain",
		"--cache-dir", t.TempDir(),
	})
	if err := root.ExecuteContext(context.Background()); err != nil {
		t.Fatalf("execute: %v\nstderr: %s", err, stderr.String())
	}
	out := stdout.String()
	for _, want := range []string{"main.tf", "variables.tf", "alpha", "beta"} {
		if !strings.Contains(out, want) {
			t.Errorf("plain output missing %q\n--- output ---\n%s", want, out)
		}
	}
}

func TestDiffIdenticalVersionsNoChanges(t *testing.T) {
	srv := fakeCrowTwoVersions(t)
	root := NewRootCmd()
	var stdout bytes.Buffer
	root.SetOut(&stdout)
	root.SetArgs([]string{
		"diff",
		"iac/comply/aws", "1.0.0", "1.0.0",
		"--crow-url", srv.URL,
		"--plain",
		"--cache-dir", t.TempDir(),
	})
	if err := root.ExecuteContext(context.Background()); err != nil {
		t.Fatalf("execute: %v", err)
	}
	if got := strings.TrimSpace(stdout.String()); got != "no differences" {
		t.Errorf("output = %q, want \"no differences\"", got)
	}
}

func TestDiffBadModuleAddress(t *testing.T) {
	root := NewRootCmd()
	var stderr bytes.Buffer
	root.SetErr(&stderr)
	root.SetArgs([]string{"diff", "bad-address", "1.0.0", "1.1.0"})
	err := root.ExecuteContext(context.Background())
	if err == nil {
		t.Fatal("expected error for bad address")
	}
	if ExitCode(err) != 1 {
		t.Errorf("exit code = %d, want 1", ExitCode(err))
	}
}

package cmd

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"

	"github.com/spf13/cobra"

	"github.com/immuta/operations/apps/birdseye/internal/archive"
	"github.com/immuta/operations/apps/birdseye/internal/diff"
	"github.com/immuta/operations/apps/birdseye/internal/registry"
	"github.com/immuta/operations/services/crow/pkg/api"
	"github.com/immuta/operations/services/crow/pkg/client"
)

// diffOpts holds the resolved options for `birdseye diff`.
type diffOpts struct {
	Semantic bool
	Plain    bool
	CacheDir string
}

const maxArchiveBytes = 50 << 20 // 50 MiB safety cap on uncompressed size

func newDiffCmd(g *GlobalFlags) *cobra.Command {
	o := &diffOpts{}
	c := &cobra.Command{
		Use:   "diff [module] [versionA] [versionB]",
		Short: "Diff two versions of a Crow module",
		Long: "Diff two versions of a module hosted in Crow.\n\n" +
			"If module/versions are omitted, the interactive TUI launches\n" +
			"(see picker task). With --plain, prints unified diff to stdout.",
		Args:          cobra.MaximumNArgs(3),
		SilenceUsage:  true,
		SilenceErrors: true,
		RunE: func(cmd *cobra.Command, args []string) error {
			return runDiff(cmd.Context(), cmd, args, g, o)
		},
	}
	c.Flags().BoolVar(&o.Semantic, "semantic", false, "include HCL-aware semantic diff alongside textual")
	c.Flags().BoolVar(&o.Plain, "plain", false, "force plain (non-TUI) output")
	c.Flags().BoolVar(&o.Plain, "no-tui", false, "alias for --plain")
	c.Flags().StringVar(&o.CacheDir, "cache-dir", defaultCacheDir(), "module tarball cache directory")
	return c
}

func defaultCacheDir() string {
	if home, err := os.UserCacheDir(); err == nil {
		return filepath.Join(home, "birdseye")
	}
	return ".birdseye-cache"
}

func newHTTPClient(d time.Duration) *http.Client {
	return &http.Client{Timeout: d}
}

func parseModuleAddress(s string) (api.ModuleIdentifier, error) {
	parts := strings.Split(s, "/")
	if len(parts) != 3 {
		return api.ModuleIdentifier{}, fmt.Errorf("%w: module address must be namespace/name/provider, got %q", ErrUsage, s)
	}
	id := api.ModuleIdentifier{Namespace: parts[0], Name: parts[1], Provider: parts[2]}
	if err := id.Validate(); err != nil {
		return api.ModuleIdentifier{}, fmt.Errorf("%w: %v", ErrUsage, err)
	}
	return id, nil
}

func runDiff(ctx context.Context, cmd *cobra.Command, args []string, g *GlobalFlags, o *diffOpts) error {
	if len(args) == 0 {
		// Interactive flow lives in Task 15; for now fall through to error.
		return fmt.Errorf("%w: interactive mode not yet implemented; provide <module> <versionA> <versionB>", ErrUsage)
	}
	if len(args) != 3 {
		return fmt.Errorf("%w: diff requires <module> <versionA> <versionB>", ErrUsage)
	}
	id, err := parseModuleAddress(args[0])
	if err != nil {
		return err
	}
	if err := api.ValidateVersion(args[1]); err != nil {
		return fmt.Errorf("%w: %v", ErrUsage, err)
	}
	if err := api.ValidateVersion(args[2]); err != nil {
		return fmt.Errorf("%w: %v", ErrUsage, err)
	}
	modA := api.Module{ModuleIdentifier: id, Version: args[1]}
	modB := api.Module{ModuleIdentifier: id, Version: args[2]}

	cli := client.New(g.CrowURL, client.WithHTTPClient(newHTTPClient(g.Timeout)))
	cache, err := registry.NewDiskCache(o.CacheDir)
	if err != nil {
		return fmt.Errorf("cache init: %w", err)
	}
	reg := registry.New(cli, cache)

	aBytes, bBytes, err := reg.FetchPair(ctx, modA, modB)
	if err != nil {
		return err
	}

	modAExtracted, err := archive.Extract(aBytes, maxArchiveBytes)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrArchive, err)
	}
	modBExtracted, err := archive.Extract(bBytes, maxArchiveBytes)
	if err != nil {
		return fmt.Errorf("%w: %v", ErrArchive, err)
	}

	result := diff.Result{Files: diff.Textual(modAExtracted, modBExtracted)}
	// Semantic mode wired in Task 17.
	// TUI mode wired in Task 13.

	return renderPlain(cmd.OutOrStdout(), result)
}

// renderPlain writes the diff result to w in unified-diff format.
// "no differences" is emitted when there are zero files in the result.
func renderPlain(w io.Writer, r diff.Result) error {
	if len(r.Files) == 0 {
		_, err := fmt.Fprintln(w, "no differences")
		return err
	}
	for i, fd := range r.Files {
		if i > 0 {
			_, _ = fmt.Fprintln(w)
		}
		_, _ = fmt.Fprintf(w, "=== %s (%s) +%d -%d\n", fd.Path, fd.Status, fd.Adds, fd.Dels)
		_, _ = fmt.Fprint(w, fd.Unified)
	}
	return nil
}

